import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/8d99bf143d7a45bd8426973e723765ff.C2W5mk8d.png",o="/bzygq/assets/780ef29f5ed340fab2e719d92c5d8f2a.B5oa820M.png",p="/bzygq/assets/f8e85d0edcef4a77818f7aa09baac8f2.sMjKdgZm.png",F=JSON.parse('{"title":"04 OpenFeign 与 LoadBalancer 服务调用链路","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/Spring Cloud/04-OpenFeign与LoadBalancer服务调用链路.md","filePath":"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/Spring Cloud/04-OpenFeign与LoadBalancer服务调用链路.md","lastUpdated":1788929995000}'),d={name:"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/Spring Cloud/04-OpenFeign与LoadBalancer服务调用链路.md"};function l(g,e,c,s,T,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_04-openfeign-与-loadbalancer-服务调用链路" tabindex="-1">04 OpenFeign 与 LoadBalancer 服务调用链路 <a class="header-anchor" href="#_04-openfeign-与-loadbalancer-服务调用链路" aria-label="Permalink to &quot;04 OpenFeign 与 LoadBalancer 服务调用链路&quot;">​</a></h1><p>OpenFeign 是 Spring Cloud 体系中的声明式 HTTP 客户端，它的核心作用是把“手写 HTTP 请求”的重复劳动收敛到 Java 接口声明中。开发者在接口上使用 @FeignClient 指定服务名或 URL，在方法上使用 Spring MVC 注解描述路径、HTTP 方法、请求参数、请求体和返回类型，业务代码调用这个接口方法时，表面上像一次本地方法调用，实际运行时会经过动态代理、请求模板组装、编码解码、服务发现、客户端负载均衡和底层 HTTP 执行。</p><p>这类组件容易被误解为“把远程调用变简单了，所以风险也变小了”。更准确的理解是：OpenFeign 只是把远程调用的代码写法变得声明式，它没有消除网络调用本身的不确定性。服务名可能找不到实例，实例列表可能延迟，目标实例可能假死，连接可能建立失败，响应可能超时，JSON 可能解析失败，重试可能造成重复写入。学习这一章时，要把 Feign 看成“服务调用链路的门面”，把 LoadBalancer、超时、连接池、重试、幂等、熔断和观测看成这条链路真正能稳定落地的配套能力。</p><h2 id="一、openfeign-解决的工程问题" tabindex="-1">一、OpenFeign 解决的工程问题 <a class="header-anchor" href="#一、openfeign-解决的工程问题" aria-label="Permalink to &quot;一、OpenFeign 解决的工程问题&quot;">​</a></h2><p>在没有声明式客户端时，服务之间调用通常要手写 RestTemplate、WebClient 或底层 HTTP 客户端代码：拼接 URL、设置请求头、序列化参数、处理状态码、反序列化响应、捕获异常。随着服务数量增加，这些样板代码会散落在业务方法中，调用方既要关心业务流程，又要关心 HTTP 细节，接口契约也难以统一维护。</p><p>OpenFeign 把这部分逻辑抽象为“接口契约”。例如订单服务需要调用库存服务，只需要定义一个 InventoryClient，在接口上声明远程服务名，在方法上声明扣减库存接口。业务层调用 inventoryClient.deduct(...) 时，Feign 会把方法调用转换为 HTTP 请求。这样做的价值主要有三点：第一，远程接口以 Java 接口形式集中管理，调用关系更清晰；第二，编码、解码、日志、拦截器、错误处理、超时等公共能力可以统一配置；第三，结合服务发现后，调用方不需要写死目标服务 IP 和端口。</p><p>但是，OpenFeign 的边界也必须说清楚。它不是 RPC 框架意义上的强约束协议，也不是服务治理的全部。Feign 默认仍然走 HTTP 语义，接口契约缺少编译期的强服务端约束，运行时依赖注册中心、负载均衡器、HTTP 客户端和 JSON 编解码。它适合同步请求响应式调用，尤其适合查询、校验、轻量业务协作；对于高吞吐事件流、耗时任务、批量异步处理、跨服务最终一致性通知，更常见的选择是 MQ、任务队列或事件驱动。</p><p>面试中回答 Feign 的定位，可以先说一句完整定义：OpenFeign 是 Spring Cloud 对 Feign 的集成，用接口和注解声明 HTTP 调用契约，并通过动态代理在运行期生成请求。随后补上边界：它降低了调用代码复杂度，但底层仍然是远程网络调用，所以必须配置超时、连接池、重试、熔断、降级和链路追踪。</p><h2 id="二、-feignclient-代理是怎样创建的" tabindex="-1">二、@FeignClient 代理是怎样创建的 <a class="header-anchor" href="#二、-feignclient-代理是怎样创建的" aria-label="Permalink to &quot;二、@FeignClient 代理是怎样创建的&quot;">​</a></h2><p>@FeignClient 的关键不是注解本身，而是它背后的 Bean 注册与代理创建过程。应用启动时，@EnableFeignClients 会触发 Feign 客户端扫描，框架找到被 @FeignClient 标记的接口后，不会直接实例化接口，而是为每个接口注册一个 FeignClientFactoryBean。这个 FactoryBean 在容器创建 Bean 时负责构建真正的 Feign 代理对象。</p><p>代理创建过程可以按五步理解。第一，解析接口上的 @FeignClient，得到 name、contextId、url、path、configuration、fallback 等元信息。第二，为该客户端准备一组独立配置，包括 Encoder、Decoder、Contract、Client、Retryer、Logger、RequestInterceptor、ErrorDecoder。第三，根据接口方法上的 Spring MVC 注解生成方法元数据，例如路径、请求方式、参数位置、请求体类型。第四，通过 Feign.Builder 创建动态代理，常见链路会进入 ReflectiveFeign 和 InvocationHandler。第五，业务调用接口方法时，代理根据方法元数据创建请求模板，再交给后续执行链路。</p><p>这里有一个容易混淆的点：@FeignClient(name = &quot;order-service&quot;) 中的 name 不是固定域名，而是服务 ID。没有显式 url 时，Feign 会把服务 ID 交给 Spring Cloud LoadBalancer，由它从注册中心提供的实例列表中选择一个真实实例。如果配置了 url，则更像直连外部 HTTP 地址，通常不会走按服务名发现实例的链路。</p><p>项目中建议每个远程服务定义独立 Client 接口，不要把多个服务的接口混在一个大 Client 里，也不要在 Feign 接口中写业务编排逻辑。Feign 接口描述的是远程服务契约，业务编排应该留在 service 层。这样做的好处是调用边界清晰，超时、日志、错误处理和熔断策略也能按下游服务维度配置。</p><h2 id="三、请求模板、编码解码与错误处理" tabindex="-1">三、请求模板、编码解码与错误处理 <a class="header-anchor" href="#三、请求模板、编码解码与错误处理" aria-label="Permalink to &quot;三、请求模板、编码解码与错误处理&quot;">​</a></h2><p>Feign 方法被调用后，第一件事不是马上发请求，而是先把方法调用转换成 RequestTemplate。请求模板中包含 HTTP method、path、query、headers、body、charset、Content-Type 等信息。方法参数会根据注解被放到不同位置：@PathVariable 进入路径变量，@RequestParam 进入 query，@RequestHeader 进入请求头，@RequestBody 进入请求体。</p><p>编码由 Encoder 负责，解码由 Decoder 负责。在 Spring Cloud OpenFeign 中，常见 JSON 编解码会复用 Spring Web 的 HttpMessageConverters，所以它和 Spring MVC 控制器的序列化习惯比较接近。实际项目中要特别注意时间格式、枚举值、BigDecimal 精度、空字段策略、泛型返回值、分页对象、字段命名风格和 Content-Type。Feign 调用链路里的很多问题并不是“服务没有调通”，而是“HTTP 成功返回了，但调用方无法按预期解析”。</p><p>错误处理要区分 HTTP 层错误和业务层错误。HTTP 4xx、5xx 通常会触发 Feign 异常或进入 ErrorDecoder；而业务返回码为失败但 HTTP 状态码仍然是 200 的情况，需要调用方在统一响应结构中解析业务码。工程中最好统一约定：哪些错误用 HTTP 状态码表达，哪些错误用业务码表达，错误响应中是否包含可观测的 traceId、错误码、错误消息和可脱敏的上下文。否则调用方会出现大量 try-catch 和字符串判断，后期维护成本很高。</p><p>下面是一个常见的配置骨架，用于说明 Feign 客户端可以按服务维度配置参数。具体数值要结合项目 SLA、调用链整体超时预算和压测结果调整，不能照抄。</p><p>spring: cloud: openfeign: client: config: inventory-service: connectTimeout: 1000 readTimeout: 3000 loggerLevel: basic httpclient: hc5: enabled: true</p><p>排查编解码问题时，可以沿着四个问题走：请求是否按预期生成，目标服务是否收到相同路径和参数，响应的状态码与 Content-Type 是否正确，返回体结构是否与调用方 DTO 匹配。不要只看 Feign 接口方法签名，真正在线上决定结果的是模板、请求头、消息转换器和返回结构。</p><h2 id="四、服务发现到实例选择的调用主链路" tabindex="-1">四、服务发现到实例选择的调用主链路 <a class="header-anchor" href="#四、服务发现到实例选择的调用主链路" aria-label="Permalink to &quot;四、服务发现到实例选择的调用主链路&quot;">​</a></h2><p>Feign 与 LoadBalancer 结合后，一次典型调用可以拆成“代理入口、模板生成、服务发现、实例选择、地址替换、HTTP 执行、响应解码”七个阶段。业务代码调用 Feign 接口方法，动态代理根据方法元数据生成 RequestTemplate；模板中的服务名会被 LoadBalancer 识别；LoadBalancer 通过 ServiceInstanceListSupplier 获取实例列表；实例选择策略挑出一个目标实例；请求中的逻辑服务名被替换为真实 host 和 port；底层 HTTP 客户端发送请求；响应再经过 Decoder 转回 Java 对象。</p><p><img src="'+r+'" alt="images/04-feign-call-chain.png"></p><p>images/04-feign-call-chain.png</p><p>这张链路图可以帮助理解两个边界。第一，注册中心通常不在每次业务请求中转发流量。消费者从注册中心获取实例列表后，会在本地选择实例并直接调用目标服务。第二，Feign 和 LoadBalancer 的责任不同。Feign 负责把接口调用转换成 HTTP 请求，LoadBalancer 负责从候选实例里选一个，底层 HTTP 客户端负责连接复用、发送请求和接收响应。</p><p>源码表达不需要背到每一行，但要能说出关键对象。FeignClientFactoryBean 负责创建代理，ReflectiveFeign 和方法处理器负责把接口方法转换为请求，RequestTemplate 承载请求模板，Client 执行 HTTP 请求，LoadBalancerClient 或相关拦截链负责按服务名选择实例，Decoder 与 ErrorDecoder 负责响应和异常转换。面试官追问“Feign 为什么像本地调用”时，答案是动态代理；继续追问“它怎样找到服务实例”时，答案要落到服务发现和 LoadBalancer。</p><h2 id="五、loadbalancer-的实例列表、缓存、健康检查与灰度-hints" tabindex="-1">五、LoadBalancer 的实例列表、缓存、健康检查与灰度 hints <a class="header-anchor" href="#五、loadbalancer-的实例列表、缓存、健康检查与灰度-hints" aria-label="Permalink to &quot;五、LoadBalancer 的实例列表、缓存、健康检查与灰度 hints&quot;">​</a></h2><p>Spring Cloud LoadBalancer 是客户端负载均衡组件。客户端负载均衡的特点是：调用方本地拿到候选实例列表，自己选择一个实例，然后直接发请求。它与 Nginx、云负载均衡这类集中式代理不同，后者是请求先到代理层，由代理层转发到后端实例。</p><p>LoadBalancer 的实例选择通常由一组 ServiceInstanceListSupplier 串联完成。底层 supplier 从 DiscoveryClient 拿实例列表，上层 supplier 可以做缓存、健康检查、zone 过滤、权重过滤、hint 过滤、粘性实例等处理。默认轮询策略能覆盖基础场景，但真实系统往往还要考虑实例元数据。比如同机房优先可以减少跨机房延迟，权重可以承接不同规格实例，灰度版本可以按请求头或用户标签只打到 v2 实例。</p><p><img src="'+o+'" alt="images/04-loadbalancer-instance-selection.png"></p><p>images/04-loadbalancer-instance-selection.png</p><p>缓存是 LoadBalancer 的重要工程参数。实例列表如果每次调用都去注册中心拉取，会增加注册中心压力，也会放大调用延迟；因此生产环境通常会使用缓存。缓存 TTL 太长，实例下线后调用方可能继续打到旧实例；TTL 太短，注册中心和客户端刷新压力会上升。官方默认缓存有 TTL 和容量配置，也可以接入 Caffeine。若某些注册中心客户端自身已经有缓存，要注意避免多层缓存导致实例状态过度滞后。</p><p>健康检查用于减少“注册表显示可用但实例实际不可用”的问题。LoadBalancer 可以通过健康检查 supplier 访问实例的健康端点，例如 /actuator/health，只把健康实例交给后续选择策略。但健康检查不是越频繁越好，频率太高会增加被调服务压力，频率太低又不能及时发现故障。实际项目要结合注册中心健康状态、应用 Actuator 端点、被动失败统计和熔断结果综合判断。</p><p>灰度 hints 适合做精细路由。Spring Cloud LoadBalancer 支持把 hint 传入负载均衡请求，也支持通过默认的 X-SC-LB-Hint 请求头进行 hint 过滤。项目里可以把实例 metadata 标记为 version=v1、version=v2、zone=shanghai、group=gray，再由网关、拦截器或自定义 supplier 根据用户标签、租户、请求头筛选目标实例。回答灰度时不要只说“加个版本号”，要补上实例元数据、请求标识、过滤策略、兜底策略和观测指标。</p><h2 id="六、超时、重试、连接池与幂等设计" tabindex="-1">六、超时、重试、连接池与幂等设计 <a class="header-anchor" href="#六、超时、重试、连接池与幂等设计" aria-label="Permalink to &quot;六、超时、重试、连接池与幂等设计&quot;">​</a></h2><p><img src="'+p+'" alt="images/04-feign-timeout-retry-idempotency.png"></p><p>images/04-feign-timeout-retry-idempotency.png</p><p>Feign 调用必须有超时预算。连接超时控制建立连接的等待时间，读取超时控制请求发出后等待响应的时间。连接超时过短会让偶发网络抖动变成失败，读取超时过长会占用调用方线程和连接，导致下游慢响应拖垮上游。更合理的做法是从入口请求的整体 SLA 倒推每个下游调用的预算，例如入口接口要求 2 秒内返回，那么一个下游调用不能配置 30 秒读取超时。</p><p>重试要和幂等绑定讨论。查询接口、状态检查接口、短暂网络失败可以有限重试；下单、扣库存、扣余额、发券、创建任务、发送通知这类写接口不能盲目重试。一次网络超时并不代表服务端没有执行成功，如果调用方再次发送请求，可能造成重复扣减或重复创建。写接口如果确实需要重试，必须有业务唯一号、请求流水号、去重表、数据库唯一索引、状态机或乐观锁。</p><p>连接池决定高并发下的调用吞吐。Feign 底层可以使用 Apache HttpClient 5、OkHttp 等客户端，不同客户端有自己的最大连接数、每路由连接数、连接复用、空闲连接回收和 socket timeout 配置。连接池太小会导致请求排队，连接池太大又可能把压力全部打到下游。连接池、业务线程池、熔断隔离和数据库连接池要一起看，否则排查时容易只调一个参数，却没有解决资源链路的瓶颈。</p><p>下面这张表可以作为面试和项目复盘的参数表达模板。</p><table tabindex="0"><thead><tr><th>参数或能力</th><th>解决的问题</th><th>误用风险</th><th>项目表达</th></tr></thead><tbody><tr><td>connectTimeout</td><td>控制建连等待</td><td>过短导致抖动失败，过长占住调用线程</td><td>按网络环境和下游部署位置设置</td></tr><tr><td>readTimeout</td><td>控制响应等待</td><td>过长放大慢调用，过短误杀正常请求</td><td>按接口 SLA 和整体超时预算设置</td></tr><tr><td>连接池最大连接数</td><td>提升连接复用和吞吐</td><td>太小排队，太大压垮下游</td><td>按服务维度和压测结果配置</td></tr><tr><td>LoadBalancer retry</td><td>对瞬时失败换实例重试</td><td>非幂等写接口重复执行</td><td>只对安全接口或具备幂等的接口开放</td></tr><tr><td>熔断降级</td><td>下游异常时保护上游</td><td>fallback 掩盖真实问题</td><td>核心链路保留告警和日志</td></tr><tr><td>请求幂等号</td><td>防止重复写入</td><td>只传号不落库无法防重</td><td>唯一索引、去重表或状态机兜底</td></tr></tbody></table><h2 id="七、feign-调用的常见失败场景与排查路径" tabindex="-1">七、Feign 调用的常见失败场景与排查路径 <a class="header-anchor" href="#七、feign-调用的常见失败场景与排查路径" aria-label="Permalink to &quot;七、Feign 调用的常见失败场景与排查路径&quot;">​</a></h2><p>Feign 调用失败不能只看一个异常栈，要先把失败分层。第一层是客户端创建失败，例如 @FeignClient 扫描不到、服务名重复、配置类冲突、版本依赖不匹配。第二层是服务发现失败，例如注册中心没有目标服务、命名空间或 group 不一致、服务名写错、实例列表为空。第三层是负载均衡失败，例如所有实例被过滤掉、hint 不匹配、健康检查结果为空、缓存过期策略不合理。第四层是 HTTP 执行失败，例如连接超时、读取超时、连接池耗尽、TLS 配置错误。第五层是响应处理失败，例如状态码异常、JSON 结构不匹配、枚举值无法反序列化、业务错误码没有被统一处理。</p><p>线上排查可以按这个顺序进行。先看调用方日志中是否有 traceId、目标服务名、目标实例、耗时、状态码和异常类型；再看注册中心中目标服务是否有健康实例；接着看 LoadBalancer 是否因为 zone、hint、灰度 metadata 把实例过滤空；然后看调用方连接池、线程池、熔断指标和重试次数；最后进入下游服务，检查 P95/P99、错误率、慢 SQL、第三方接口耗时和最近发布记录。</p><p>几个典型问题可以提前准备回答。No instances available for xxx 通常优先排查服务名、命名空间、注册状态和消费者是否拿到实例列表。偶发 Read timed out 通常排查下游慢响应、数据库慢 SQL、线程池拥塞和读取超时是否合理。大量 Connection refused 可能是实例端口不可用、实例刚下线但缓存未刷新、容器探针或发布过程异常。解析失败则优先看响应体、Content-Type、字段类型和调用方 DTO。</p><p>还要注意观测信息的完整性。Feign 日志级别可以帮助定位请求与响应，但生产环境不能无脑开启 FULL 级别，否则会带来性能开销和敏感数据泄露风险。更推荐在关键接口记录脱敏后的请求摘要、响应码、耗时、目标实例、业务错误码和 traceId。这样既能排查问题，又不会把用户隐私、Token、密码或内部密钥打进日志。</p><h2 id="八、项目表达-把调用链路讲成真实工程" tabindex="-1">八、项目表达：把调用链路讲成真实工程 <a class="header-anchor" href="#八、项目表达-把调用链路讲成真实工程" aria-label="Permalink to &quot;八、项目表达：把调用链路讲成真实工程&quot;">​</a></h2><p>项目里描述 OpenFeign 与 LoadBalancer，可以从“调用契约、实例选择、稳定性保护、观测排查”四个层次展开。一个比较完整的回答是：我们把服务间同步 HTTP 调用封装为独立 Feign Client，接口只描述稳定契约，不承载业务编排；服务实例通过 Nacos 注册发现，调用方按服务名拿实例列表，再由 Spring Cloud LoadBalancer 结合缓存、zone、metadata 和灰度 hint 选择目标实例；不同下游按 SLA 配置连接超时、读取超时、连接池和日志级别；查询接口可以有限重试，写接口必须先做幂等；核心依赖接入熔断降级，线上通过 traceId、目标实例、耗时和错误码排查。</p><p>以 IoT 项目为例，设备服务查询用户权限可以通过 Feign 调用户服务，告警服务查询设备信息可以通过 Feign 调设备服务，任务服务创建巡检任务时可能需要同步校验设备状态。读多写少的查询链路可以配置较短超时和有限重试；创建任务、扣减资源、状态变更这类写链路要携带业务流水号并做幂等；第三方通知、告警推送、批量数据上报不适合全部同步 Feign 串行调用，更适合 MQ 或异步任务解耦。</p><p>面试追问“Feign 有哪些坑”时，可以答得更工程化。第一，把 Feign 当成本地调用，导致一个接口里串行调用多个下游，整体延迟不可控。第二，所有接口共用默认超时，慢接口拖垮线程池，快接口又被过短超时误伤。第三，对写接口开启重试却没有幂等，造成重复业务操作。第四，灰度规则只在网关做了，服务间调用没有带灰度标识，导致入口命中 v2，内部又调用到 v1。第五，异常处理不统一，HTTP 状态码、业务错误码和 Feign 异常混在一起，用户层看到的是框架异常。</p><p>更好的项目表达不是“我们用了 Feign”，而是“我们把 Feign 作为服务契约入口，把 LoadBalancer 作为实例选择层，把超时、重试、连接池、熔断、幂等和链路追踪作为稳定性设计”。这句话能把组件使用和工程治理联系起来，也能自然承接线上排查、灰度发布和容量规划追问。</p><h2 id="九、学习自测" tabindex="-1">九、学习自测 <a class="header-anchor" href="#九、学习自测" aria-label="Permalink to &quot;九、学习自测&quot;">​</a></h2><p><strong>1. OpenFeign 为什么不能理解成本地调用？</strong></p><p>参考回答：OpenFeign 只是让调用写法像接口方法调用，底层仍然是 HTTP 远程调用。它仍然会遇到服务发现失败、实例列表延迟、连接超时、读取超时、连接池耗尽、响应解析失败、下游 5xx、重复请求等问题。所以回答时要强调“声明式封装降低代码复杂度，不改变远程调用的不可靠性”。</p><p><strong>2. @FeignClient(name = &quot;inventory-service&quot;) 中的 name 在调用链路中有什么作用？</strong></p><p>参考回答：没有配置固定 url 时，name 通常作为服务 ID 使用。Feign 生成请求后，会把这个服务 ID 交给 LoadBalancer，LoadBalancer 根据注册中心提供的实例列表选择一个真实 host 和 port，再发起 HTTP 调用。它不是写死的域名，也不是注册中心帮忙转发业务请求。</p><p><strong>3. RequestTemplate 主要保存哪些信息？</strong></p><p>参考回答：RequestTemplate 保存一次 Feign 方法调用生成的 HTTP 请求模板，包括 HTTP 方法、路径、query 参数、请求头、请求体、编码信息和 Content-Type 等。它是接口方法元数据与真实 HTTP 请求之间的中间表示。</p><p><strong>4. LoadBalancer 的缓存 TTL 太长或太短分别有什么问题？</strong></p><p>参考回答：TTL 太长时，实例下线、发布、故障摘除后，调用方可能继续使用旧实例，导致调用失败；TTL 太短时，客户端和注册中心刷新压力上升，调用链路也可能增加不必要的开销。工程中要结合注册中心自身缓存、发布频率、故障摘除速度和调用量设置。</p><p><strong>5. 为什么非幂等写接口不适合盲目重试？</strong></p><p>参考回答：超时只说明调用方没有在规定时间内拿到结果，并不能证明服务端没有执行成功。如果写接口在服务端已经扣库存或创建订单，调用方再次重试可能导致重复扣减或重复创建。写接口需要重试时，必须设计业务唯一号、去重表、唯一索引、状态机或乐观锁。</p><p><strong>6. Feign 调用偶发读取超时，应从哪些方向排查？</strong></p><p>参考回答：先看调用方超时配置和整体 SLA，再看下游 P95/P99、线程池、连接池、数据库慢 SQL、Redis 或第三方接口耗时；同时检查是否存在重试放大、熔断未生效、实例灰度不均、单实例过载和最近发布变更。只调大 readTimeout 通常不是根本解决。</p><p><strong>7. 灰度发布中为什么服务间 Feign 调用也要考虑灰度标识？</strong></p><p>参考回答：入口网关命中灰度版本后，如果内部 Feign 调用没有继续传递用户标签、版本 hint 或灰度请求头，LoadBalancer 可能选到稳定版本实例，导致一次请求跨版本流转。正确做法是让灰度标识贯穿网关、调用方拦截器、LoadBalancer 过滤策略和实例 metadata。</p><p><strong>8. 面试中如何用一句话总结 Feign 与 LoadBalancer 的关系？</strong></p><p>参考回答：Feign 负责把 Java 接口方法转换成 HTTP 请求，LoadBalancer 负责根据服务发现得到的实例列表选择一个目标实例，二者组合完成“按服务名发起远程 HTTP 调用”的主链路；稳定落地还需要超时、连接池、重试、熔断、幂等和观测配合。</p>',69)])])}const m=a(d,[["render",l]]);export{F as __pageData,m as default};
